import type { CatalogItem } from './CatalogItem'
import type { VariableSet } from './VariableSet'
import type { VariableReference } from './Variable'

/**
 * Type representing the properties of a Catalog UI Policy.
 */
type CatalogUiPolicyTarget = {
    /** The catalog item the policy applies to. Mutually exclusive with variableSet. */
    catalogItem?: string | CatalogItem
    /** The applies to the policy. */
    appliesTo?: 'item' | 'set'
    /** The variable set the policy applies to. Mutually exclusive with catalogItem. */
    variableSet?: string | VariableSet
}

/**
 * Supported UI types for catalog UI policies
 */
export type CatalogUiPolicyUIType = 'desktop' | 'mobileOrServicePortal' | 'all'

/**
 * Supported message types for field messages
 */
export type FieldMessageType = 'info' | 'warning' | 'error'

/**
 * Supported value actions
 */
export type ValueAction = 'clearValue' | 'setValue'

/**
 * Interface for catalog UI policy action configuration
 */
export type CatalogUiPolicyAction = {
    /**
     * Name of the variable this action applies to
     */
    variableName: string | VariableReference
    /** Whether the field should be visible */
    visible?: boolean
    /** Whether the field should be mandatory */
    mandatory?: boolean
    /** Whether the field should be disabled */
    readOnly?: boolean
    /**
     * Whether the field should be cleared when the policy is triggered
     */
    cleared?: boolean
    /**
     * Value to set when the policy is triggered
     */
    value?: string
    /**
     * Action to take on the field value
     */
    valueAction?: ValueAction
    /**
     * Order in which the action should be executed
     */
    order?: number
    /** Type of field message to display */
    variableMessageType?: FieldMessageType
    /** Message to display on the field */
    variableMessage?: string
}

/**
 * Interface for catalog UI policy configuration
 */
export type CatalogUiPolicyConfig = {
    /** Short description of the UI policy */
    shortDescription: string
    /** Whether the UI policy is active */
    active?: boolean
    /** Whether the UI policy applies globally */
    global?: boolean
    /** Whether the UI policy runs on page load */
    onLoad?: boolean
    /** Whether the UI policy runs scripts */
    runScripts?: boolean
    /** Whether to reverse the policy condition logic */
    reverseIfFalse?: boolean
    /** Whether to isolate the script execution context */
    isolateScript?: boolean
    /** Condition to determine when the policy applies to the catalog */
    catalogCondition?: string
    /** Whether the policy applies when viewing the catalog item */
    appliesOnCatalogItemView?: boolean
    /** Whether the policy applies on the target record */
    appliesOnTargetRecord?: boolean
    /** Whether the policy applies on catalog tasks */
    appliesOnCatalogTasks?: boolean
    /** Whether the policy applies on requested items */
    appliesOnRequestedItems?: boolean
    /** Script to execute when the policy condition is true */
    executeIfTrue?: string
    /** Script to execute when the policy condition is false */
    executeIfFalse?: string
    /** Detailed description of the UI policy */
    description?: string
    /** Order in which the policy should be evaluated */
    order?: number
    /** UI type(s) where the policy should run */
    runScriptsInUiType?: CatalogUiPolicyUIType
    /** Whether the policy is supported for virtual agents */
    vaSupported?: boolean
    /**
     * Actions to take when the policy is triggered
     */
    actions?: CatalogUiPolicyAction[]
} & CatalogUiPolicyTarget

/**
 * Type representing the properties of a Catalog UI Policy with ID.
 */
export type CatalogUiPolicyProps = Now.Internal.WithID<CatalogUiPolicyConfig>

/**
 * Creates a new catalog UI policy
 * @param config Configuration for the catalog UI policy
 */
export function CatalogUiPolicy(config: CatalogUiPolicyProps) {
    return config
}
